let activityState=null;async function loadActivityState(){if(activityState)return activityState;const{data,error}=await supabaseClient.from(`user_activity_state`).select(`*`).eq(`user_id`,currentUser.id).maybeSingle();const now=new Date().toISOString();const fresh={user_id:currentUser.id,last_seen_amis:now,last_seen_groupes:now,last_digest_at:now,last_seen_changelog:now};if(error){console.error(error);activityState=fresh;return activityState}if(data){activityState=data}else{const{data:inserted,error:insErr}=await supabaseClient.from(`user_activity_state`).upsert(fresh,{onConflict:`user_id`}).select().maybeSingle();if(insErr){console.error(insErr);activityState=fresh}else activityState=inserted}return activityState}async function markSeen(category){await loadActivityState();const now=new Date().toISOString();const col=category===`amis`?`last_seen_amis`:`last_seen_groupes`;activityState[col]=now;const{error}=await supabaseClient.from(`user_activity_state`).upsert({user_id:currentUser.id,[col]:now},{onConflict:`user_id`});if(error)console.error(error);refreshActivityBadge()}async function markDigestSeen(){await loadActivityState();const now=new Date().toISOString();activityState.last_digest_at=now;const{error}=await supabaseClient.from(`user_activity_state`).upsert({user_id:currentUser.id,last_digest_at:now},{onConflict:`user_id`});if(error)console.error(error)}async function hasUnread(category){await loadActivityState();const col=category===`amis`?`last_seen_amis`:`last_seen_groupes`;const scope=category===`amis`?`friend`:`group`;const since=activityState&&activityState[col];if(!since)return false;const{data,error}=await supabaseClient.from(`activity_events`).select(`id`).eq(`scope`,scope).neq(`actor_id`,currentUser.id).gt(`created_at`,since).limit(1);if(error){console.error(error);return false}return(data||[]).length>0}async function hasPendingIncomingFriendRequest(){const{count,error}=await supabaseClient.from(`friendships`).select(`id`,{count:`exact`,head:true}).eq(`addressee_id`,currentUser.id).eq(`status`,`pending`);if(error){console.error(error);return false}return(count||0)>0}async function refreshActivityBadge(){if(!currentUser)return;const[amis,groupes,pendingRequest]=await Promise.all([hasUnread(`amis`),hasUnread(`groupes`),hasPendingIncomingFriendRequest()]);const unread=amis||groupes||pendingRequest;document.getElementById(`friendsBtn`).classList.toggle(`has-unread`,unread);document.getElementById(`mobileTabFriends`).classList.toggle(`has-unread`,unread)}async function loadDigest(){await loadActivityState();const fourteenDaysAgo=new Date(Date.now()-14*24*60*60*1e3).toISOString();const since=activityState.last_digest_at&&activityState.last_digest_at>fourteenDaysAgo?activityState.last_digest_at:fourteenDaysAgo;const{data,error}=await supabaseClient.from(`activity_events`).select(`*`).in(`scope`,[`friend`,`group`]).neq(`actor_id`,currentUser.id).gt(`created_at`,since).order(`created_at`,{ascending:false}).limit(20);if(error){console.error(error);return[]}const events=data.map(rowToActivityEvent);const missing=[...new Set(events.map(e=>e.actorId))].filter(id=>!friendProfiles[id]);if(missing.length){const{data:profs,error:profErr}=await supabaseClient.from(`profiles`).select(`user_id, display_name, avatar_url`).in(`user_id`,missing);if(profErr)console.error(profErr);else profs.forEach(p=>cacheProfile(p.user_id,p.display_name,p.avatar_url))}return events}async function maybeShowDigest(){const events=await loadDigest();const banner=document.getElementById(`activityDigestBanner`);if(events.length===0){banner.style.display=`none`;banner.innerHTML=``;return}banner.innerHTML=`
    <div class="digest-title">Depuis ta dernière visite</div>
    <div class="wl-list">${events.map(renderActivityRowHtml).join(``)}</div>
    <button class="btn secondary" id="digestDismissBtn" type="button">Marquer comme vu</button>
  `;banner.style.display=``;document.getElementById(`digestDismissBtn`).addEventListener(`click`,async()=>{banner.style.display=`none`;banner.innerHTML=``;await markDigestSeen()})}const INACTIVITY_REMINDER_DAYS=21;function daysSinceLastRating(){if(films.length===0)return null;const mostRecent=Math.max(...films.map(f=>f.added));return Math.floor((Date.now()-mostRecent)/(1e3*60*60*24))}function maybeShowInactivityReminder(){const banner=document.getElementById(`inactivityReminderBanner`);const days=daysSinceLastRating();if(days===null||days<INACTIVITY_REMINDER_DAYS){banner.style.display=`none`;banner.innerHTML=``;return}const mostRecentAdded=Math.max(...films.map(f=>f.added));let dismissedFor=null;try{dismissedFor=localStorage.getItem(`kinetInactivityDismissedFor`)}catch(e){}if(dismissedFor===String(mostRecentAdded)){banner.style.display=`none`;banner.innerHTML=``;return}banner.innerHTML=`
    <div class="ir-note">
      <div class="ir-title">Ça fait ${days} jours que tu n'as rien noté</div>
      <div class="ir-sub">Un film récemment vu à ajouter à ton catalogue ?</div>
      <div class="ir-actions">
        <button class="ir-link is-accent" id="inactivityReminderAddBtn" type="button">+ Ajouter un film</button>
        <button class="ir-link" id="inactivityReminderDismissBtn" type="button">Plus tard</button>
      </div>
    </div>
  `;banner.style.display=``;document.getElementById(`inactivityReminderAddBtn`).addEventListener(`click`,()=>{banner.style.display=`none`;openModal()});document.getElementById(`inactivityReminderDismissBtn`).addEventListener(`click`,()=>{banner.style.display=`none`;banner.innerHTML=``;try{localStorage.setItem(`kinetInactivityDismissedFor`,String(mostRecentAdded))}catch(e){}})}